$:set -euo pipefail
node <<'NODE'
"use strict";
const fs=require("node:fs"),cp=require("node:child_process"),crypto=require("node:crypto");
const dir="workspaces/codespace-mcp-srs-design/local-terminals/templates/";
const file=dir+"agent-return-wrapper.json";
for(const p of ["AGENTS.md","terminals_requirements.json","workspaces/codespace-mcp-srs-design/README.md","workspaces/codespace-mcp-srs-design/AGENTS.md",dir+"agent-command-return.schema.json",dir+"agent-command-templates.json",file])if(!fs.existsSync(p))throw Error("Missing governing or target file: "+p);
if(!fs.readFileSync("AGENTS.md","utf8").includes("DISCOVERY-04"))throw Error("Governing execution contract missing");
const origin=fs.readFileSync(file,"utf8"),data=JSON.parse(origin);
if(data.version!=="1.0.0"||data.derivations.length!==37)throw Error("Unexpected wrapper version or number of derivations");
const sourceSchema=JSON.parse(fs.readFileSync(dir+"agent-command-return.schema.json","utf8"));
if(data.compatibility.source_schema_id!==sourceSchema.$id)throw Error("Source schema mismatch");
const omitted=data.derivations.filter(d=>d.id==="DER-034");
if(omitted.length!==1||omitted[0].output_pointer!=="/derived/declared_coverage_complete")throw Error("Targeted unsafe completeness derivation missing");
data.derivations=data.derivations.filter(d=>d.id!=="DER-034");
data.version="1.1.0";
data.constraints.coverage="Coverage may be copied or grouped exclusively as reported in the source. The wrapper must not calculate a global completeness or success guarantee from declared coverage.";
data.constraints.missing_inputs="For each optional input, evaluate the stated prerequisites without interpretation. If missing, omit the corresponding derived field or entry. Never replace missing values or unobserved collections with zeros, nulls, false, or empty arrays.";
data.constraints.deterministic_derivations="Every retained operation is a pure function of explicitly supplied, schema-valid source values; derived entries with absent preconditions are omitted. In particular, evidence of absent events is not inferred from an unpopulated collection.";
data.verification.required_checks=data.verification.required_checks.map(s=>s==="All 37 derivations have unique IDs and output locations"?"All 36 retained derivations have unique IDs and output locations":s);
data.verification.required_checks.push("No derived global completeness claim is emitted. Coverage observations remain source declarations only.");
data.verification.source_revision="1.0.0";
data.change_log=[{version:"1.1.0",removed:["DER-034"],reason:"Declared coverage statuses alone cannot establish global observational completeness; retain only source-supported deterministic enrichment."}];
const ids=new Set(data.derivations.map(x=>x.id));
if(data.derivations.length!==36||ids.size!==36||ids.has("DER-034"))throw Error("Unexpected retained derivations");
for(const d of data.derivations){if(!d.output_pointer||!d.operation||!d.inputs?.length||!d.when)throw Error("Invalid derivation "+d.id)}
const replacement=JSON.stringify(data,null,2)+"\n";
const get=p=>JSON.parse(cp.execFileSync("gh",["api","repos/BestNameYet/Terminals/contents/"+p],{encoding:"utf8"}));
const prior=get(file);
if(Buffer.from(prior.content.replace(/\s/g,""),"base64").toString("utf8")!==origin)throw Error("Remote differs from expected original");
const payload={branch:"main",message:"docs(local-terminals): remove non-verifiable coverage-completeness derivation",sha:prior.sha,content:Buffer.from(replacement).toString("base64")};
const response=JSON.parse(cp.execFileSync("gh",["api","-X","PUT","repos/BestNameYet/Terminals/contents/"+file,"--input","-"],{encoding:"utf8",input:JSON.stringify(payload)}));
const final=Buffer.from(get(file).content.replace(/\s/g,""),"base64").toString("utf8");
if(final!==replacement)throw Error("Remote readback failed");
const verified=JSON.parse(final);
if(verified.derivations.length!==36||verified.derivations.some(d=>d.id==="DER-034"))throw Error("Remote content validation failed");
console.log(JSON.stringify({path:file,commit:response.commit.sha,version:verified.version,derivations:verified.derivations.length,removed:["DER-034"],sha256:crypto.createHash("sha256").update(final).digest("hex"),verified:true}));
NODE
